const abs = (p) => new URL(p, BASE).href;
const relOf = (url) => (url.startsWith(BASE) ? url.slice(BASE.length).split(/[?#]/)[0] : null);
const cacheable = (res) => res && res.ok && res.status === 200 && (res.type === 'basic' || res.type === 'default');

async function broadcast(msg) {
  const list = await self.clients.matchAll({ includeUncontrolled: true, type: 'window' });
  for (const c of list) c.postMessage(msg);
}

/** Previous precache (newest other version) and its { path: hash } map, for reuse. */
async function previousPrecache() {
  const names = (await caches.keys()).filter((n) => n.startsWith(`${PREFIX}precache-`) && n !== PRECACHE_NAME);
  for (const name of names.reverse()) {
    const cache = await caches.open(name);
    const meta = await cache.match(abs(META_KEY));
    if (!meta) continue;
    try {
      return { cache, hashes: await meta.json() };
    } catch {
      /* unreadable: try the next one */
    }
  }
  return null;
}

async function precache() {
  const cache = await caches.open(PRECACHE_NAME);
  const prev = await previousPrecache();
  const hashes = {};
  let done = 0;
  let lastReport = 0;
  const queue = PRECACHE.slice();
  const worker = async () => {
    for (;;) {
      const item = queue.shift();
      if (!item) return;
      const [path, hash] = item;
      const url = abs(path);
      let res = null;
      if (prev && prev.hashes[path] === hash && hash) res = await prev.cache.match(url);
      if (!res) {
        res = await fetch(new Request(url, { cache: 'no-cache', credentials: 'same-origin' }));
        if (res.status === 404) {
          // Listed but no longer on the server: the app cannot need it.
          done++;
          continue;
        }
        if (!cacheable(res)) throw new Error(`precache ${path}: HTTP ${res.status}`);
      }
      await cache.put(url, res);
      hashes[path] = hash;
      done++;
      if (done - lastReport >= 8 || done === PRECACHE.length) {
        lastReport = done;
        broadcast({ type: 'vibora-sw-progress', version: VERSION, done, total: PRECACHE.length });
      }
    }
  };
  await Promise.all(Array.from({ length: 6 }, worker));
  await cache.put(abs(META_KEY), new Response(JSON.stringify(hashes), { headers: { 'Content-Type': 'application/json' } }));
}

self.addEventListener('install', (event) => {
  event.waitUntil(precache());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keep = new Set([PRECACHE_NAME, RUNTIME_NAME]);
    for (const name of await caches.keys()) {
      if (name.startsWith(PREFIX) && !keep.has(name)) await caches.delete(name);
    }
    if (self.registration.navigationPreload) {
      try {
        await self.registration.navigationPreload.disable();
      } catch {
        /* not supported */
      }
    }
    await self.clients.claim();
    broadcast({ type: 'vibora-sw-ready', version: VERSION });
  })());
});

async function fromCache(url) {
  const pre = await caches.open(PRECACHE_NAME);
  const hit = await pre.match(url, { ignoreSearch: true });
  if (hit) return hit;
  const rt = await caches.open(RUNTIME_NAME);
  return rt.match(url, { ignoreSearch: true });
}

function timeout(ms) {
  return new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), ms));
}

/** Network first (revalidated), cache fallback; fresh copies replace the cached ones. */
async function networkFirst(request, key) {
  try {
    // A navigation request cannot be re-initialised; everything else is revalidated.
    const net = request.mode === 'navigate' ? fetch(request) : fetch(request, { cache: 'no-cache' });
    const res = await Promise.race([net, timeout(NETWORK_TIMEOUT_MS)]);
    if (cacheable(res)) {
      const copy = res.clone();
      caches.open(PRECACHE_NAME).then((c) => c.put(key, copy)).catch(() => {});
      return res;
    }
    if (res.status < 500) return res; // a real 404 etc.: pass it on
    throw new Error(`HTTP ${res.status}`);
  } catch (err) {
    const hit = await fromCache(key);
    if (hit) return hit;
    throw err;
  }
}

/** Cache first; misses are fetched and kept in the runtime cache. */
async function cacheFirst(request, key) {
  const hit = await fromCache(key);
  if (hit) return hit;
  const res = await fetch(request);
  if (cacheable(res)) {
    const copy = res.clone();
    caches.open(RUNTIME_NAME).then((c) => c.put(key, copy)).catch(() => {});
  }
  return res;
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || req.headers.has('range')) return;
  const rel = relOf(req.url);
  if (rel === null) return; // other origins (and paths outside the scope): not ours
  if (rel === 'sw.js' || rel.startsWith('tools/') || rel.startsWith('tests/')) return;
  // The app's page is cached once as index.html, whatever its query (?source=app, ?drill=…).
  const key = rel === '' || rel === 'index.html' ? abs('index.html') : abs(rel);
  if (req.mode === 'navigate') {
    event.respondWith(networkFirst(req, key));
    return;
  }
  event.respondWith(IMMUTABLE.test(rel) ? cacheFirst(req, key) : networkFirst(req, key));
});

async function cacheUrls(urls) {
  const rt = await caches.open(RUNTIME_NAME);
  for (const u of urls || []) {
    const rel = typeof u === 'string' ? relOf(u) : null;
    if (rel === null || rel === '' || rel === 'sw.js' || /^(tools|tests|dev)\//.test(rel)) continue;
    const key = abs(rel);
    if (await fromCache(key)) continue;
    try {
      const res = await fetch(key, { cache: 'no-cache' });
      if (cacheable(res)) await rt.put(key, res);
    } catch {
      /* offline: next time */
    }
  }
}

async function status() {
  const pre = await caches.open(PRECACHE_NAME);
  const keys = await pre.keys();
  const have = new Set(keys.map((r) => r.url));
  const missing = PRECACHE.filter(([p]) => !have.has(abs(p))).map(([p]) => p);
  return { version: VERSION, precached: PRECACHE.length - missing.length, total: PRECACHE.length, missing: missing.slice(0, 20) };
}

self.addEventListener('message', (event) => {
  const msg = event.data || {};
  const reply = (data) => {
    if (event.ports && event.ports[0]) event.ports[0].postMessage(data);
    else if (event.source) event.source.postMessage(data);
  };
  if (msg.type === 'SKIP_WAITING') {
    self.skipWaiting();
  } else if (msg.type === 'CACHE_URLS') {
    event.waitUntil(cacheUrls(msg.urls).then(() => reply({ type: 'vibora-sw-cached' })));
  } else if (msg.type === 'STATUS') {
    event.waitUntil(status().then((s) => reply({ type: 'vibora-sw-status', ...s })));
  }
});
